const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Antarctic region
  const antarctic = ee.Geometry.Rectangle([-180, -90, 180, -60]);

  // Define dates
  const octDate = '2021-10-07';
  const janDate = '2021-01-01';

  // Get ozone data - using MODIS ozone product
  const octCollection = ee.ImageCollection('MODIS/061/MOD08_D3')
    .filterDate(octDate, ee.Date(octDate).advance(1, 'day'))
    .filterBounds(antarctic);

  const janCollection = ee.ImageCollection('MODIS/061/MOD08_D3')
    .filterDate(janDate, ee.Date(janDate).advance(1, 'day'))
    .filterBounds(antarctic);

  // Check if collections have data
  const octSize = octCollection.size().getInfo();
  const janSize = janCollection.size().getInfo();

  console.log(`October 7, 2021 Images: ${octSize}`);
  console.log(`January 1, 2021 Images: ${janSize}`);

  if (octSize === 0 || janSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get first images
  const octImage = octCollection.first();
  const janImage = janCollection.first();

  // Define ozone hole as areas with total ozone < 220 Dobson Units
  const ozoneHoleOct = octImage.select('TotalOzone').lt(220);
  const ozoneHoleJan = janImage.select('TotalOzone').lt(220);

  // Calculate areas in square km
  const areaOct = ozoneHoleOct.multiply(ee.Image.pixelArea()).divide(1e6);
  const areaJan = ozoneHoleJan.multiply(ee.Image.pixelArea()).divide(1e6);

  // Reduce regions
  const octStats = areaOct.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: antarctic,
    scale: 25000,
    maxPixels: 1e9
  });

  const janStats = areaJan.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: antarctic,
    scale: 25000,
    maxPixels: 1e9
  });

  const octArea = octStats.get('TotalOzone').getInfo();
  const janArea = janStats.get('TotalOzone').getInfo();

  console.log(`Oct 7 Ozone Hole Area: ${octArea ? octArea.toFixed(0) : 'N/A'} km²`);
  console.log(`Jan 1 Ozone Hole Area: ${janArea ? janArea.toFixed(0) : 'N/A'} km²`);

  // Check for valid results
  if (octArea === null || janArea === null || isNaN(octArea) || isNaN(janArea)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare areas
  if (octArea > janArea) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
